1	package httpapi
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"net/http"
8		"time"
9	
10		"github.com/lansolocoder/cla03-entitlement-service/internal/entitlements"
11	)
12	
13	// Service is the entitlement domain surface the HTTP layer needs.
14	type Service interface {
15		CreateEntitlement(ctx context.Context, in entitlements.CreateEntitlementInput) (entitlements.Entitlement, error)
16		CreateReservation(ctx context.Context, entitlementID, reservationID string, amount int64) (entitlements.Reservation, bool, error)
17		SettleReservation(ctx context.Context, entitlementID, reservationID, action string) (entitlements.Reservation, error)
18		ReverseReservation(ctx context.Context, entitlementID, reservationID, reversalID string) (entitlements.Reversal, bool, error)
19		CreateAdjustment(ctx context.Context, entitlementID, adjustmentID string, delta int64, effectiveAt time.Time) (entitlements.Adjustment, bool, error)
20		RescheduleEntitlement(ctx context.Context, entitlementID, rescheduleID string, newValidFrom, newValidTo time.Time) (entitlements.Reschedule, bool, error)
21		GetView(ctx context.Context, entitlementID string) (entitlements.View, error)
22	}
23	
24	func New(checkDatabase func(context.Context) error, service Service) http.Handler {
25		mux := http.NewServeMux()
26		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
27			respond(w, http.StatusOK, `{"status":"ok"}`)
28		})
29		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
30			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
31			defer cancel()
32			if err := checkDatabase(ctx); err != nil {
33				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
34				return
35			}
36			respond(w, http.StatusOK, `{"status":"ready"}`)
37		})
38	
39		h := &handlers{service: service}
40		mux.HandleFunc("POST /entitlements", h.createEntitlement)
41		mux.HandleFunc("GET /entitlements/{entitlementID}", h.getEntitlement)
42		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations", h.createReservation)
43		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/confirm", h.settle(entitlements.ActionConfirm))
44		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/release", h.settle(entitlements.ActionRelease))
45		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/reverse", h.reverseReservation)
46		mux.HandleFunc("POST /entitlements/{entitlementID}/adjustments", h.createAdjustment)
47		mux.HandleFunc("POST /entitlements/{entitlementID}/reschedules", h.createReschedule)
48		return mux
49	}
50	
51	type handlers struct {
52		service Service
53	}
54	
55	type createEntitlementRequest struct {
56		EntitlementID string `json:"entitlement_id"`
57		SeatsTotal    *int64 `json:"seats_total"`
58		QuotaTotal    *int64 `json:"quota_total"`
59		ValidFrom     string `json:"valid_from"`
60		ValidTo       string `json:"valid_to"`
61	}
62	
63	func (h *handlers) createEntitlement(w http.ResponseWriter, r *http.Request) {
64		var req createEntitlementRequest
65		if !decode(w, r, &req) {
66			return
67		}
68		validFrom, errFrom := time.Parse(time.RFC3339, req.ValidFrom)
69		validTo, errTo := time.Parse(time.RFC3339, req.ValidTo)
70		if req.ValidFrom == "" || req.ValidTo == "" || errFrom != nil || errTo != nil {
71			respondError(w, &entitlements.Error{
72				Code:    entitlements.CodeInvalidRequest,
73				Message: "valid_from and valid_to must be RFC 3339 timestamps, e.g. 2026-01-01T00:00:00Z",
74			})
75			return
76		}
77		ent, err := h.service.CreateEntitlement(r.Context(), entitlements.CreateEntitlementInput{
78			EntitlementID: req.EntitlementID,
79			SeatsTotal:    req.SeatsTotal,
80			QuotaTotal:    req.QuotaTotal,
81			ValidFrom:     validFrom,
82			ValidTo:       validTo,
83		})
84		if err != nil {
85			respondError(w, err)
86			return
87		}
88		respondJSON(w, http.StatusCreated, ent)
89	}
90	
91	type createReservationRequest struct {
92		ReservationID string `json:"reservation_id"`
93		Amount        *int64 `json:"amount"`
94	}
95	
96	func (h *handlers) createReservation(w http.ResponseWriter, r *http.Request) {
97		var req createReservationRequest
98		if !decode(w, r, &req) {
99			return
100		}
101		if req.Amount == nil {
102			respondError(w, &entitlements.Error{
103				Code:    entitlements.CodeInvalidRequest,
104				Message: "amount is required and must be a positive integer",
105			})
106			return
107		}
108		reservation, created, err := h.service.CreateReservation(
109			r.Context(), r.PathValue("entitlementID"), req.ReservationID, *req.Amount)
110		if err != nil {
111			respondError(w, err)
112			return
113		}
114		status := http.StatusOK
115		if created {
116			status = http.StatusCreated
117		}
118		respondJSON(w, status, reservation)
119	}
120	
121	func (h *handlers) settle(action string) http.HandlerFunc {
122		return func(w http.ResponseWriter, r *http.Request) {
123			reservation, err := h.service.SettleReservation(
124				r.Context(), r.PathValue("entitlementID"), r.PathValue("reservationID"), action)
125			if err != nil {
126				respondError(w, err)
127				return
128			}
129			respondJSON(w, http.StatusOK, reservation)
130		}
131	}
132	
133	type reverseReservationRequest struct {
134		ReversalID string `json:"reversal_id"`
135	}
136	
137	func (h *handlers) reverseReservation(w http.ResponseWriter, r *http.Request) {
138		var req reverseReservationRequest
139		if !decode(w, r, &req) {
140			return
141		}
142		reversal, created, err := h.service.ReverseReservation(
143			r.Context(), r.PathValue("entitlementID"), r.PathValue("reservationID"), req.ReversalID)
144		if err != nil {
145			respondError(w, err)
146			return
147		}
148		status := http.StatusOK
149		if created {
150			status = http.StatusCreated
151		}
152		respondJSON(w, status, reversal)
153	}
154	
155	type createAdjustmentRequest struct {
156		AdjustmentID string `json:"adjustment_id"`
157		Delta        *int64 `json:"delta"`
158		EffectiveAt  string `json:"effective_at"`
159	}
160	
161	func (h *handlers) createAdjustment(w http.ResponseWriter, r *http.Request) {
162		var req createAdjustmentRequest
163		if !decode(w, r, &req) {
164			return
165		}
166		if req.Delta == nil || *req.Delta == 0 {
167			respondError(w, &entitlements.Error{
168				Code:    entitlements.CodeInvalidRequest,
169				Message: "delta is required and must be a non-zero integer",
170			})
171			return
172		}
173		effectiveAt, err := time.Parse(time.RFC3339, req.EffectiveAt)
174		if req.EffectiveAt == "" || err != nil {
175			respondError(w, &entitlements.Error{
176				Code:    entitlements.CodeInvalidRequest,
177				Message: "effective_at must be an RFC 3339 timestamp, e.g. 2026-06-01T00:00:00Z",
178			})
