1118			if view.Reschedules[i].RescheduleID != wantID ||
1119				view.Reschedules[i].NewValidFrom.IsZero() || view.Reschedules[i].NewValidTo.IsZero() ||
1120				view.Reschedules[i].CreatedAt.IsZero() {
1121				t.Fatalf("reschedule entry %d: %+v", i, view.Reschedules[i])
1122			}
1123		}
1124		// The view's window reflects the latest reschedule.
1125		last := view.Reschedules[2]
1126		if !view.ValidFrom.Equal(last.NewValidFrom) || !view.ValidTo.Equal(last.NewValidTo) || view.Status != "expired" {
1127			t.Fatalf("view window should reflect latest reschedule: %+v", view)
1128		}
1129	}
1130	
1131	func TestConcurrentReschedulesRewriteOnce(t *testing.T) {
1132		store := testStore(t)
1133		from, to := activeWindow()
1134		id := uniqueID(t)
1135		mustCreate(t, store, id, 100, from, to)
1136		ctx := context.Background()
1137		newFrom := time.Now().Add(-time.Hour).UTC().Truncate(time.Microsecond)
1138		newTo := time.Now().Add(2 * time.Hour).UTC().Truncate(time.Microsecond)
1139	
1140		// Many workers submit the same reschedule identifier and also hammer the
1141		// entitlement with quota operations; all serialize on the row lock.
1142		const workers = 8
1143		var wg sync.WaitGroup
1144		errs := make(chan error, workers*4)
1145		for w := 0; w < workers; w++ {
1146			wg.Add(1)
1147			go func(w int) {
1148				defer wg.Done()
1149				if _, _, err := store.RescheduleEntitlement(ctx, id, "move-1", newFrom, newTo); err != nil {
1150					errs <- err
1151				}
1152				if _, _, err := store.RescheduleEntitlement(ctx, id, "move-1", newFrom, newTo); err != nil {
1153					errs <- err
1154				}
1155				rid := fmt.Sprintf("res-%d", w)
1156				if _, _, err := store.CreateReservation(ctx, id, rid, 5); err != nil {
1157					errs <- err
1158					return
1159				}
1160				_, _ = store.SettleReservation(ctx, id, rid, ActionConfirm)
1161			}(w)
1162		}
1163		wg.Wait()
1164		close(errs)
1165		for err := range errs {
1166			t.Fatalf("unexpected concurrent failure: %v", err)
1167		}
1168		view, err := store.GetView(ctx, id)
1169		if err != nil {
1170			t.Fatalf("view: %v", err)
1171		}
1172		if len(view.Reschedules) != 1 || !view.ValidFrom.Equal(newFrom) || !view.ValidTo.Equal(newTo) {
1173			t.Fatalf("reschedule applied more than once: %+v", view)
1174		}
1175		if view.UsedAmount != workers*5 || view.QuotaTotal != 100 ||
1176			view.AvailableAmount != 100-view.UsedAmount {
1177			t.Fatalf("quota state after concurrent reschedules: %+v", view)
1178		}
1179	}
1180	
1181	func TestReschedulesSurviveReconnection(t *testing.T) {
1182		store := testStore(t)
1183		from, to := activeWindow()
1184		id := uniqueID(t)
1185		mustCreate(t, store, id, 100, from, to)
1186		ctx := context.Background()
1187		newFrom := time.Now().Add(-time.Hour).UTC().Truncate(time.Microsecond)
1188		newTo := time.Now().Add(-time.Minute).UTC().Truncate(time.Microsecond)
1189		if _, _, err := store.RescheduleEntitlement(ctx, id, "move-1", newFrom, newTo); err != nil {
1190			t.Fatalf("reschedule: %v", err)
1191		}
1192	
1193		// A fresh pool over the same database simulates a service restart.
1194		pool, err := pgxpool.New(ctx, os.Getenv("TEST_DATABASE_URL"))
1195		if err != nil {
1196			t.Fatalf("reconnect: %v", err)
1197		}
1198		defer pool.Close()
1199		restarted := NewStore(pool)
1200		view, err := restarted.GetView(ctx, id)
1201		if err != nil {
1202			t.Fatalf("view after restart: %v", err)
1203		}
1204		if !view.ValidFrom.Equal(newFrom) || !view.ValidTo.Equal(newTo) ||
1205			view.Status != "expired" || len(view.Reschedules) != 1 {
1206			t.Fatalf("rescheduled window lost across restart: %+v", view)
1207		}
1208		// The reschedule identifier is still replayed, not re-applied.
1209		replay, created, err := restarted.RescheduleEntitlement(ctx, id, "move-1", newFrom, newTo)
1210		if err != nil || created || !replay.NewValidFrom.Equal(newFrom) {
1211			t.Fatalf("reschedule replay after restart: %+v created=%v err=%v", replay, created, err)
1212		}
1213		// New reservations stay blocked by the persisted, already-expired window.
1214		_, _, err = restarted.CreateReservation(ctx, id, "res-1", 1)
1215		wantCode(t, err, CodeEntitlementNotActive)
1216	}
