		r.Context(), r.PathValue("entitlementID"), req.SeatAdjustmentID, *req.Delta)
	if err != nil {
		respondError(w, err)
		return
	}
	status := http.StatusOK
	if created {
		status = http.StatusCreated
	}
	respondJSON(w, status, adjustment)
}

